sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
layout(color) uniform half4 shadowColor;
uniform float shadowOpacity;
uniform float offsetDist;
uniform float angle;
uniform float spread;
uniform float shadowOnly;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 off = float2(cos(radians(angle)), sin(radians(angle))) * offsetDist;
    float sa = float4(blurred.eval(clamp(coord - off, float2(0.0), size))).a;
    sa = saturate(sa * (1.0 + spread * 4.0)) * shadowOpacity;
    float4 shadow = float4(float3(shadowColor.rgb) * sa, sa);
    float4 r = shadowOnly > 0.5 ? shadow : c + shadow * (1.0 - c.a);
    return fin(c, r, opacity);
}
